#!/usr/bin/env node

/**
 * Task-local validator for skill folders (mirrors the skill-creator validator).
 *
 * Usage:
 *   node validate_slack_skill.cjs <skill-directory>
 */

const fs = require('node:fs');
const path = require('node:path');

function validateSkill(skillPath) {
  if (!fs.existsSync(skillPath) || !fs.statSync(skillPath).isDirectory()) {
    return { valid: false, message: `Path is not a directory: ${skillPath}` };
  }
  const skillMdPath = path.join(skillPath, 'SKILL.md');
  if (!fs.existsSync(skillMdPath)) {
    return { valid: false, message: 'SKILL.md not found' };
  }
  const content = fs.readFileSync(skillMdPath, 'utf8');
  if (!content.startsWith('---')) {
    return { valid: false, message: 'No YAML frontmatter found' };
  }
  const parts = content.split('---');
  if (parts.length < 3) {
    return { valid: false, message: 'Invalid frontmatter format' };
  }
  const frontmatterText = parts[1];

  const nameMatch = frontmatterText.match(/^name:\s*(.+)$/m);
  const descMatch = frontmatterText.match(
    /^description:\s*(?:'([^']*)'|"([^"]*)"|(.+))$/m,
  );
  if (!nameMatch) return { valid: false, message: 'Missing "name" in frontmatter' };
  if (!descMatch) {
    return { valid: false, message: 'Description must be a single-line string: description: ...' };
  }

  const name = nameMatch[1].trim();
  const description = (
    descMatch[1] !== undefined
      ? descMatch[1]
      : descMatch[2] !== undefined
        ? descMatch[2]
        : descMatch[3] || ''
  ).trim();

  if (description.includes('\n')) {
    return { valid: false, message: 'Description must be a single line (no newlines)' };
  }
  if (!/^[a-z0-9-]+$/.test(name)) {
    return { valid: false, message: `Name "${name}" should be hyphen-case` };
  }
  if (description.length > 1024) {
    return { valid: false, message: 'Description is too long (max 1024)' };
  }

  const files = getAllFiles(skillPath);
  for (const file of files) {
    const fileContent = fs.readFileSync(file, 'utf8');
    if (fileContent.includes('TODO:')) {
      return {
        valid: true,
        message: 'Skill has unresolved TODOs',
        warning: `Found unresolved TODO in ${path.relative(skillPath, file)}`,
      };
    }
  }

  return { valid: true, message: 'Skill is valid!' };
}

function getAllFiles(dir, fileList = []) {
  const files = fs.readdirSync(dir);
  files.forEach((file) => {
    const name = path.join(dir, file);
    if (fs.statSync(name).isDirectory()) {
      if (!['node_modules', '.git', '__pycache__'].includes(file)) {
        getAllFiles(name, fileList);
      }
    } else {
      fileList.push(name);
    }
  });
  return fileList;
}

if (require.main === module) {
  const args = process.argv.slice(2);
  if (args.length !== 1) {
    process.stderr.write('Usage: node validate_slack_skill.cjs <skill-directory>\n');
    process.exit(1);
  }
  const result = validateSkill(path.resolve(args[0]));
  if (result.warning) process.stderr.write(`Warning: ${result.warning}\n`);
  if (result.valid) {
    process.stdout.write(`Success: ${result.message}\n`);
  } else {
    process.stderr.write(`Failure: ${result.message}\n`);
    process.exit(1);
  }
}

module.exports = { validateSkill };

#!/usr/bin/env node

/**
 * Task-local packager: validates a skill folder and packages it into a
 * distributable .skill file (a zip archive) using only Node built-ins.
 *
 * Usage:
 *   node package_slack_skill.cjs <skill-folder> [output-directory]
 */

const fs = require('node:fs');
const path = require('node:path');
const zlib = require('node:zlib');
const { validateSkill } = require('./validate_slack_skill.cjs');

const DOS_TIME = (11 << 11) | (30 << 5) | (30 >> 1); // 11:30:30
const DOS_DATE = ((2024 - 1980) << 9) | (1 << 5) | 1; // 2024-01-01

let crcTable = null;
function crc32(buf) {
  if (!crcTable) {
    crcTable = new Int32Array(256);
    for (let n = 0; n < 256; n++) {
      let c = n;
      for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
      crcTable[n] = c;
    }
  }
  let crc = -1;
  for (let i = 0; i < buf.length; i++) crc = (crc >>> 8) ^ crcTable[(crc ^ buf[i]) & 0xff];
  return (crc ^ -1) >>> 0;
}

function walk(dir, base, out = []) {
  const entries = fs.readdirSync(dir).sort();
  for (const entry of entries) {
    const full = path.join(dir, entry);
    const rel = path.relative(base, full).split(path.sep).join('/');
    const stat = fs.statSync(full);
    if (stat.isDirectory()) {
      out.push({ name: `${rel}/`, isDir: true });
      walk(full, base, out);
    } else {
      out.push({ name: rel, isDir: false, data: fs.readFileSync(full) });
    }
  }
  return out;
}

function localHeader(entry, nameBuf, compressed, crc) {
  const buf = Buffer.alloc(30);
  buf.writeUInt32LE(0x04034b50, 0); // local file header signature
  buf.writeUInt16LE(20, 4); // version needed
  buf.writeUInt16LE(0, 6); // flags
  buf.writeUInt16LE(entry.isDir ? 0 : 8, 8); // stored for dirs, deflate otherwise
  buf.writeUInt16LE(DOS_TIME, 10);
  buf.writeUInt16LE(DOS_DATE, 12);
  buf.writeUInt32LE(crc, 14);
  buf.writeUInt32LE(compressed.length, 18);
  buf.writeUInt32LE(entry.isDir ? 0 : entry.data.length, 22);
  buf.writeUInt16LE(nameBuf.length, 26);
  buf.writeUInt16LE(0, 28); // extra field length
  return Buffer.concat([buf, nameBuf, compressed]);
}

function centralHeader(entry, nameBuf, compressed, crc, offset) {
  const buf = Buffer.alloc(46);
  buf.writeUInt32LE(0x02014b50, 0); // central directory signature
  buf.writeUInt16LE(20, 4); // version made by
  buf.writeUInt16LE(20, 6); // version needed
  buf.writeUInt16LE(0, 8); // flags
  buf.writeUInt16LE(entry.isDir ? 0 : 8, 10); // method
  buf.writeUInt16LE(DOS_TIME, 12);
  buf.writeUInt16LE(DOS_DATE, 14);
  buf.writeUInt32LE(crc, 16);
  buf.writeUInt32LE(compressed.length, 20);
  buf.writeUInt32LE(entry.isDir ? 0 : entry.data.length, 24);
  buf.writeUInt16LE(nameBuf.length, 28);
  buf.writeUInt16LE(0, 30); // extra
  buf.writeUInt16LE(0, 32); // comment
  buf.writeUInt16LE(0, 34); // disk start
  buf.writeUInt16LE(0, 36); // internal attrs
  buf.writeUInt32LE(0, 38); // external attrs
  buf.writeUInt32LE(offset, 42); // local header offset
  return Buffer.concat([buf, nameBuf]);
}

function eocd(entryCount, centralSize, centralOffset) {
  const buf = Buffer.alloc(22);
  buf.writeUInt32LE(0x06054b50, 0); // end of central directory signature
  buf.writeUInt16LE(0, 4);
  buf.writeUInt16LE(0, 6);
  buf.writeUInt16LE(entryCount, 8);
  buf.writeUInt16LE(entryCount, 10);
  buf.writeUInt32LE(centralSize, 12);
  buf.writeUInt32LE(centralOffset, 16);
  buf.writeUInt16LE(0, 20); // comment length
  return buf;
}

function buildZip(entries) {
  const locals = [];
  const centrals = [];
  let offset = 0;
  for (const entry of entries) {
    const nameBuf = Buffer.from(entry.name, 'utf8');
    let crc = 0;
    let compressed = Buffer.alloc(0);
    if (!entry.isDir) {
      crc = crc32(entry.data);
      compressed = zlib.deflateRawSync(entry.data);
    }
    const local = localHeader(entry, nameBuf, compressed, crc);
    locals.push(local);
    centrals.push(centralHeader(entry, nameBuf, compressed, crc, offset));
    offset += local.length;
  }
  const localPart = Buffer.concat(locals);
  const centralPart = Buffer.concat(centrals);
  return Buffer.concat([
    localPart,
    centralPart,
    eocd(entries.length, centralPart.length, localPart.length),
  ]);
}

function verifyZip(filePath, expectedNames) {
  const data = fs.readFileSync(filePath);
  const eocdOffset = data.length - 22;
  if (data.readUInt32LE(eocdOffset) !== 0x06054b50) {
    throw new Error('End of central directory record not found');
  }
  const count = data.readUInt16LE(eocdOffset + 10);
  const centralSize = data.readUInt32LE(eocdOffset + 12);
  const centralOffset = data.readUInt32LE(eocdOffset + 16);
  const names = [];
  let pos = centralOffset;
  for (let i = 0; i < count; i++) {
    if (data.readUInt32LE(pos) !== 0x02014b50) {
      throw new Error(`Bad central directory entry ${i}`);
    }
    const nameLen = data.readUInt16LE(pos + 28);
    names.push(data.toString('utf8', pos + 46, pos + 46 + nameLen));
    pos += 46 + nameLen;
  }
  if (pos !== centralOffset + centralSize) {
    throw new Error('Central directory size mismatch');
  }
  const missing = expectedNames.filter((n) => !names.includes(n));
  if (missing.length) {
    throw new Error(`Missing entries in archive: ${missing.join(', ')}`);
  }
  return names;
}

async function main() {
  const args = process.argv.slice(2);
  if (args.length < 1) {
    process.stderr.write('Usage: node package_slack_skill.cjs <skill-folder> [output-directory]\n');
    process.exit(1);
  }
  const skillPath = path.resolve(args[0]);
  const outputDir = args[1] ? path.resolve(args[1]) : process.cwd();
  const skillName = path.basename(skillPath);
  const outputFile = path.join(outputDir, `${skillName}.skill`);

  process.stdout.write('Validating skill...\n');
  const result = validateSkill(skillPath);
  if (!result.valid) {
    process.stderr.write(`Failure: validation failed: ${result.message}\n`);
    process.exit(1);
  }
  if (result.warning) {
    process.stderr.write(`Failure: ${result.warning}\n`);
    process.exit(1);
  }
  process.stdout.write('Success: skill is valid\n');

  const entries = walk(skillPath, skillPath);
  const archive = buildZip(entries);
  fs.writeFileSync(outputFile, archive);
  const expected = entries.map((e) => e.name);
  const names = verifyZip(outputFile, expected);
  process.stdout.write(`Success: packaged ${names.length} entries to ${outputFile}\n`);
}

main().catch((err) => {
  process.stderr.write(`Failure: ${err.message}\n`);
  process.exit(1);
});

