#!/usr/bin/env node

/**
 * Shared Slack Web API helper used by the other scripts in this skill.
 *
 * Exports `callSlack()` and also works as a standalone CLI:
 *
 *   node slack_request.cjs <GET|POST> <api-path> [--data '<json>'] [--token <token>] [--dry-run]
 *
 * Examples:
 *   node slack_request.cjs GET /api/auth.test
 *   node slack_request.cjs POST /api/chat.postMessage --data '{"channel":"C1","text":"hi"}'
 *
 * The token is taken from --token or the SLACK_BOT_TOKEN environment variable.
 * Output is intentionally clean and truncated so it is easy for an agent to consume.
 */

const BASE_URL = 'https://slack.com';

/**
 * Perform a Slack Web API call.
 *
 * @param {object} opts
 * @param {string} opts.method  HTTP method (GET or POST)
 * @param {string} opts.path    API path, e.g. "/api/chat.postMessage"
 * @param {object|string} [opts.data] JSON body (object or string)
 * @param {string} opts.token   Bot token (xoxb-...)
 * @param {boolean} [opts.dryRun] Print the request instead of sending it
 * @returns {Promise<object>} { dryRun?, method, url, body?, status?, retryAfter?, bodyText?, parsed? }
 */
async function callSlack({ method, path: apiPath, data, token, dryRun = false }) {
  if (typeof fetch !== 'function') {
    throw new Error('fetch is not available (Node.js 18+ required)');
  }
  const url = BASE_URL + apiPath;
  const headers = { Authorization: `Bearer ${token}` };
  let body;
  if (data !== undefined && data !== null) {
    headers['Content-Type'] = 'application/json; charset=utf-8';
    body = typeof data === 'string' ? data : JSON.stringify(data);
  }
  if (dryRun) {
    return { dryRun: true, method, url, body };
  }
  const res = await fetch(url, { method, headers, body });
  const bodyText = await res.text();
  let parsed = null;
  try {
    parsed = JSON.parse(bodyText);
  } catch {
    // Non-JSON body (unexpected); parsed stays null.
  }
  return {
    dryRun: false,
    method,
    url,
    status: res.status,
    retryAfter: res.headers.get('retry-after'),
    bodyText,
    parsed,
  };
}

function truncate(text, max) {
  if (text.length <= max) return text;
  return `${text.slice(0, max)}...[truncated ${text.length - max} chars]`;
}

function parseCliArgs(argv) {
  const args = { method: null, path: null, data: null, token: null, dryRun: false };
  const positional = [];
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '--data') args.data = argv[++i];
    else if (arg === '--token') args.token = argv[++i];
    else if (arg === '--dry-run') args.dryRun = true;
    else positional.push(arg);
  }
  args.method = (positional[0] || '').toUpperCase();
  args.path = positional[1] || '';
  return args;
}

async function cliMain() {
  const args = parseCliArgs(process.argv.slice(2));
  if (!args.method || !args.path) {
    process.stderr.write(
      'Usage: node slack_request.cjs <GET|POST> <api-path> [--data <json>] [--token <token>] [--dry-run]\n',
    );
    process.exit(1);
  }
  const token = args.token || process.env.SLACK_BOT_TOKEN;
  if (!token) {
    process.stderr.write('Failure: no Slack token. Set SLACK_BOT_TOKEN or pass --token.\n');
    process.exit(1);
  }
  const result = await callSlack({
    method: args.method,
    path: args.path,
    data: args.data,
    token,
    dryRun: args.dryRun,
  });
  if (result.dryRun) {
    process.stdout.write(`Dry run: ${result.method} ${result.url}\n`);
    if (result.body) process.stdout.write(`Body: ${truncate(result.body, 2000)}\n`);
    process.stdout.write('Success: request not sent (--dry-run)\n');
    return;
  }
  if (result.status === 429) {
    process.stderr.write(
      `Failure: Slack rate limit hit (HTTP 429). Retry-After: ${result.retryAfter || '?'}s\n`,
    );
    process.exit(1);
  }
  if (!result.parsed || result.parsed.ok !== true) {
    const reason = result.parsed && result.parsed.error ? result.parsed.error : `HTTP ${result.status}`;
    process.stderr.write(`Failure: Slack API error: ${reason}\n`);
    if (result.parsed) process.stderr.write(`Details: ${truncate(JSON.stringify(result.parsed), 2000)}\n`);
    process.exit(1);
  }
  process.stdout.write(`Success: ${truncate(JSON.stringify(result.parsed), 6000)}\n`);
}

if (require.main === module) {
  cliMain().catch((err) => {
    process.stderr.write(`Failure: ${err.message}\n`);
    process.exit(1);
  });
}

module.exports = { callSlack, BASE_URL };

#!/usr/bin/env node

/**
 * Post a message to a Slack channel, or reply inside a thread.
 *
 * Usage:
 *   node post_message.cjs --channel <channel> --text <text> [--thread-ts <ts>] [--token <token>] [--dry-run]
 *
 * Examples:
 *   node post_message.cjs --channel general --text "Deploy finished"
 *   node post_message.cjs --channel C0123456789 --text "Agreed" --thread-ts 1720000000.123456
 */

const { callSlack } = require('./slack_request.cjs');

function parseArgs(argv) {
  const args = { channel: null, text: null, threadTs: null, token: null, dryRun: false };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--channel') args.channel = argv[++i];
    else if (a === '--text') args.text = argv[++i];
    else if (a === '--thread-ts') args.threadTs = argv[++i];
    else if (a === '--token') args.token = argv[++i];
    else if (a === '--dry-run') args.dryRun = true;
    else {
      process.stderr.write(`Failure: unknown argument: ${a}\n`);
      process.exit(1);
    }
  }
  return args;
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (!args.channel || !args.text) {
    process.stderr.write(
      'Usage: node post_message.cjs --channel <channel> --text <text> [--thread-ts <ts>] [--token <token>] [--dry-run]\n',
    );
    process.exit(1);
  }
  const token = args.token || process.env.SLACK_BOT_TOKEN;
  if (!token) {
    process.stderr.write('Failure: no Slack token. Set SLACK_BOT_TOKEN or pass --token.\n');
    process.exit(1);
  }
  const payload = { channel: args.channel, text: args.text };
  if (args.threadTs) payload.thread_ts = args.threadTs;
  const result = await callSlack({
    method: 'POST',
    path: '/api/chat.postMessage',
    data: payload,
    token,
    dryRun: args.dryRun,
  });
  if (result.dryRun) {
    process.stdout.write('Dry run: POST https://slack.com/api/chat.postMessage\n');
    process.stdout.write(`Body: ${JSON.stringify(payload)}\n`);
    process.stdout.write('Success: message not sent (--dry-run)\n');
    return;
  }
  if (result.status === 429) {
    process.stderr.write(
      `Failure: Slack rate limit hit (HTTP 429). Retry-After: ${result.retryAfter || '?'}s\n`,
    );
    process.exit(1);
  }
  if (!result.parsed || result.parsed.ok !== true) {
    const reason = result.parsed && result.parsed.error ? result.parsed.error : `HTTP ${result.status}`;
    process.stderr.write(`Failure: Slack API error: ${reason}\n`);
    process.exit(1);
  }
  process.stdout.write(
    `Success: message posted to ${result.parsed.channel} (ts ${result.parsed.ts})\n`,
  );
}

main().catch((err) => {
  process.stderr.write(`Failure: ${err.message}\n`);
  process.exit(1);
});

#!/usr/bin/env node

/**
 * List Slack conversations (channels, groups, DMs) in the workspace.
 *
 * Usage:
 *   node list_conversations.cjs [--types public_channel,private_channel,im,mpim] [--limit <n>] [--cursor <cursor>] [--token <token>] [--dry-run]
 *
 * Examples:
 *   node list_conversations.cjs
 *   node list_conversations.cjs --types public_channel --limit 100
 */

const { callSlack } = require('./slack_request.cjs');

function parseArgs(argv) {
  const args = {
    types: 'public_channel,private_channel',
    limit: null,
    cursor: null,
    token: null,
    dryRun: false,
  };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--types') args.types = argv[++i];
    else if (a === '--limit') args.limit = argv[++i];
    else if (a === '--cursor') args.cursor = argv[++i];
    else if (a === '--token') args.token = argv[++i];
    else if (a === '--dry-run') args.dryRun = true;
    else {
      process.stderr.write(`Failure: unknown argument: ${a}\n`);
      process.exit(1);
    }
  }
  return args;
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  const token = args.token || process.env.SLACK_BOT_TOKEN;
  if (!token) {
    process.stderr.write('Failure: no Slack token. Set SLACK_BOT_TOKEN or pass --token.\n');
    process.exit(1);
  }
  const query = new URLSearchParams({ types: args.types });
  if (args.limit) query.set('limit', args.limit);
  if (args.cursor) query.set('cursor', args.cursor);
  const path = `/api/conversations.list?${query.toString()}`;
  const result = await callSlack({ method: 'GET', path, token, dryRun: args.dryRun });
  if (result.dryRun) {
    process.stdout.write(`Dry run: GET ${result.url}\n`);
    process.stdout.write('Success: request not sent (--dry-run)\n');
    return;
  }
  if (result.status === 429) {
    process.stderr.write(
      `Failure: Slack rate limit hit (HTTP 429). Retry-After: ${result.retryAfter || '?'}s\n`,
    );
    process.exit(1);
  }
  if (!result.parsed || result.parsed.ok !== true) {
    const reason = result.parsed && result.parsed.error ? result.parsed.error : `HTTP ${result.status}`;
    process.stderr.write(`Failure: Slack API error: ${reason}\n`);
    process.exit(1);
  }
  const channels = result.parsed.channels || [];
  const show = channels.slice(0, 100);
  process.stdout.write(`Conversations (${show.length} of ${channels.length} returned):\n`);
  for (const ch of show) {
    const label = ch.name ? `#${ch.name}` : '(dm)';
    const flags = [
      ch.is_archived ? 'archived' : null,
      ch.is_private ? 'private' : null,
      ch.is_member ? 'member' : null,
    ]
      .filter(Boolean)
      .join(',');
    process.stdout.write(`  ${ch.id} ${label}${flags ? ` [${flags}]` : ''}\n`);
  }
  const next = result.parsed.response_metadata && result.parsed.response_metadata.next_cursor;
  process.stdout.write(
    `Success: listed ${channels.length} conversations${next ? ` (use --cursor ${next} for more)` : ''}\n`,
  );
}

main().catch((err) => {
  process.stderr.write(`Failure: ${err.message}\n`);
  process.exit(1);
});

#!/usr/bin/env node

/**
 * Read recent messages from a Slack channel (conversations.history).
 *
 * Usage:
 *   node fetch_history.cjs --channel <channel> [--limit <n>] [--cursor <cursor>] [--token <token>] [--dry-run]
 *
 * Examples:
 *   node fetch_history.cjs --channel C0123456789
 *   node fetch_history.cjs --channel general --limit 50
 */

const { callSlack } = require('./slack_request.cjs');

function parseArgs(argv) {
  const args = { channel: null, limit: null, cursor: null, token: null, dryRun: false };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--channel') args.channel = argv[++i];
    else if (a === '--limit') args.limit = argv[++i];
    else if (a === '--cursor') args.cursor = argv[++i];
    else if (a === '--token') args.token = argv[++i];
    else if (a === '--dry-run') args.dryRun = true;
    else {
