  return `${text.slice(0, max)}...`;
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (!args.channel) {
    process.stderr.write(
      'Usage: node fetch_history.cjs --channel <channel> [--limit <n>] [--cursor <cursor>] [--token <token>] [--dry-run]\n',
    );
    process.exit(1);
  }
  const token = args.token || process.env.SLACK_BOT_TOKEN;
  if (!token) {
    process.stderr.write('Failure: no Slack token. Set SLACK_BOT_TOKEN or pass --token.\n');
    process.exit(1);
  }
  const query = new URLSearchParams({ channel: args.channel });
  if (args.limit) query.set('limit', args.limit);
  if (args.cursor) query.set('cursor', args.cursor);
  const path = `/api/conversations.history?${query.toString()}`;
  const result = await callSlack({ method: 'GET', path, token, dryRun: args.dryRun });
  if (result.dryRun) {
    process.stdout.write(`Dry run: GET ${result.url}\n`);
    process.stdout.write('Success: request not sent (--dry-run)\n');
    return;
  }
  if (result.status === 429) {
    process.stderr.write(
      `Failure: Slack rate limit hit (HTTP 429). Retry-After: ${result.retryAfter || '?'}s\n`,
    );
    process.exit(1);
  }
  if (!result.parsed || result.parsed.ok !== true) {
    const reason = result.parsed && result.parsed.error ? result.parsed.error : `HTTP ${result.status}`;
    process.stderr.write(`Failure: Slack API error: ${reason}\n`);
    process.exit(1);
  }
  const messages = result.parsed.messages || [];
  const show = messages.slice(0, 50);
  process.stdout.write(`Messages (${show.length} of ${messages.length} returned):\n`);
  for (const msg of show) {
    const text = (msg.text || '(no text)').replace(/\n/g, ' ');
    const prefix = msg.subtype ? `[${msg.subtype}] ` : '';
    const replies = msg.reply_count ? ` (${msg.reply_count} replies)` : '';
    process.stdout.write(
      `  [${msg.ts}] ${msg.user || '?'}: ${prefix}${truncate(text, 300)}${replies}\n`,
    );
  }
  const next = result.parsed.response_metadata && result.parsed.response_metadata.next_cursor;
  process.stdout.write(
    `Success: fetched ${messages.length} messages${next ? ` (use --cursor ${next} for more)` : ''}\n`,
  );
}

main().catch((err) => {
  process.stderr.write(`Failure: ${err.message}\n`);
  process.exit(1);
});

#!/usr/bin/env node

/**
 * Search Slack messages across the workspace (search.messages).
 *
 * Usage:
 *   node search_messages.cjs --query <query> [--count <n>] [--cursor <cursor>] [--token <token>] [--dry-run]
 *
 * Examples:
 *   node search_messages.cjs --query "deploy failed"
 *   node search_messages.cjs --query "from:@alice in:#general"
 */

const { callSlack } = require('./slack_request.cjs');

function parseArgs(argv) {
  const args = { query: null, count: null, cursor: null, token: null, dryRun: false };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--query') args.query = argv[++i];
    else if (a === '--count') args.count = argv[++i];
    else if (a === '--cursor') args.cursor = argv[++i];
    else if (a === '--token') args.token = argv[++i];
    else if (a === '--dry-run') args.dryRun = true;
    else {
      process.stderr.write(`Failure: unknown argument: ${a}\n`);
      process.exit(1);
    }
  }
  return args;
}

function truncate(text, max) {
  if (text.length <= max) return text;
  return `${text.slice(0, max)}...`;
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (!args.query) {
    process.stderr.write(
      'Usage: node search_messages.cjs --query <query> [--count <n>] [--cursor <cursor>] [--token <token>] [--dry-run]\n',
    );
    process.exit(1);
  }
  const token = args.token || process.env.SLACK_BOT_TOKEN;
  if (!token) {
    process.stderr.write('Failure: no Slack token. Set SLACK_BOT_TOKEN or pass --token.\n');
    process.exit(1);
  }
  const query = new URLSearchParams({ query: args.query });
  if (args.count) query.set('count', args.count);
  if (args.cursor) query.set('cursor', args.cursor);
  const path = `/api/search.messages?${query.toString()}`;
  const result = await callSlack({ method: 'GET', path, token, dryRun: args.dryRun });
  if (result.dryRun) {
    process.stdout.write(`Dry run: GET ${result.url}\n`);
    process.stdout.write('Success: request not sent (--dry-run)\n');
    return;
  }
  if (result.status === 429) {
    process.stderr.write(
      `Failure: Slack rate limit hit (HTTP 429). Retry-After: ${result.retryAfter || '?'}s\n`,
    );
    process.exit(1);
  }
  if (!result.parsed || result.parsed.ok !== true) {
    const reason = result.parsed && result.parsed.error ? result.parsed.error : `HTTP ${result.status}`;
    process.stderr.write(`Failure: Slack API error: ${reason}\n`);
    process.exit(1);
  }
  const messageBag = result.parsed.messages;
  const matches = (messageBag && messageBag.matches) || [];
  const total = messageBag ? messageBag.total : matches.length;
  const show = matches.slice(0, 30);
  process.stdout.write(`Matches (${show.length} of ${total} total):\n`);
  for (const m of show) {
    const channel = m.channel ? (m.channel.name ? `#${m.channel.name}` : m.channel.id) : '?';
    const text = (m.text || '(no text)').replace(/\n/g, ' ');
    const user = m.user ? m.user.username || m.user : '?';
    process.stdout.write(`  [${channel} ${m.ts}] ${user}: ${truncate(text, 300)}\n`);
  }
  const next = result.parsed.response_metadata && result.parsed.response_metadata.next_cursor;
  process.stdout.write(
    `Success: found ${total} matches${next ? ` (use --cursor ${next} for more)` : ''}\n`,
  );
}

main().catch((err) => {
  process.stderr.write(`Failure: ${err.message}\n`);
  process.exit(1);
});

#!/usr/bin/env node

/**
 * List Slack workspace users (users.list).
 *
 * Usage:
 *   node list_users.cjs [--limit <n>] [--cursor <cursor>] [--token <token>] [--dry-run]
 *
 * Examples:
 *   node list_users.cjs
 *   node list_users.cjs --limit 200
 */

const { callSlack } = require('./slack_request.cjs');

function parseArgs(argv) {
  const args = { limit: null, cursor: null, token: null, dryRun: false };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--limit') args.limit = argv[++i];
    else if (a === '--cursor') args.cursor = argv[++i];
    else if (a === '--token') args.token = argv[++i];
    else if (a === '--dry-run') args.dryRun = true;
    else {
      process.stderr.write(`Failure: unknown argument: ${a}\n`);
      process.exit(1);
    }
  }
  return args;
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  const token = args.token || process.env.SLACK_BOT_TOKEN;
  if (!token) {
    process.stderr.write('Failure: no Slack token. Set SLACK_BOT_TOKEN or pass --token.\n');
    process.exit(1);
  }
  const query = new URLSearchParams({});
  if (args.limit) query.set('limit', args.limit);
  if (args.cursor) query.set('cursor', args.cursor);
  const path = `/api/users.list?${query.toString()}`;
  const result = await callSlack({ method: 'GET', path, token, dryRun: args.dryRun });
  if (result.dryRun) {
    process.stdout.write(`Dry run: GET ${result.url}\n`);
    process.stdout.write('Success: request not sent (--dry-run)\n');
    return;
  }
  if (result.status === 429) {
    process.stderr.write(
      `Failure: Slack rate limit hit (HTTP 429). Retry-After: ${result.retryAfter || '?'}s\n`,
    );
    process.exit(1);
  }
  if (!result.parsed || result.parsed.ok !== true) {
    const reason = result.parsed && result.parsed.error ? result.parsed.error : `HTTP ${result.status}`;
    process.stderr.write(`Failure: Slack API error: ${reason}\n`);
    process.exit(1);
  }
  const users = result.parsed.members || [];
  const show = users.slice(0, 100);
  process.stdout.write(`Users (${show.length} of ${users.length} returned):\n`);
  for (const u of show) {
    const name = u.name || '?';
    const real = u.real_name ? ` (${u.real_name})` : '';
    const flags = [u.is_bot ? 'bot' : null, u.deleted ? 'deleted' : null, u.is_restricted ? 'restricted' : null]
      .filter(Boolean)
      .join(',');
    process.stdout.write(`  ${u.id} ${name}${real}${flags ? ` [${flags}]` : ''}\n`);
  }
  const next = result.parsed.response_metadata && result.parsed.response_metadata.next_cursor;
  process.stdout.write(
    `Success: listed ${users.length} users${next ? ` (use --cursor ${next} for more)` : ''}\n`,
  );
}

main().catch((err) => {
  process.stderr.write(`Failure: ${err.message}\n`);
  process.exit(1);
});
